WITH recent_departments AS (SELECT *, ROUND(budget, 2) AS budget_rounded FROM departments WHERE NOT (budget >= 3858000 OR budget <= 1205000)), agg AS (SELECT location, SUM(CASE WHEN location = 'London' THEN budget_rounded ELSE 0 END) AS london_budget_rounded, SORT_ARRAY(COLLECT_SET(dept_name)) AS dept_name_list FROM recent_departments GROUP BY location) SELECT location, london_budget_rounded, dept_name_list FROM agg WHERE london_budget_rounded > 43
